/*
QUESTION:
Given two strings needle and haystack, return the index of the first occurrence of needle in haystack, or -1 if needle is not part of haystack.

Example 1:
Input: haystack = "sadbutsad", needle = "sad"
Output: 0
Explanation: "sad" occurs at index 0 and 6.
The first occurrence is at index 0, so we return 0.

Approach:
- We can solve this problem using the KMP (Knuth-Morris-Pratt) string matching algorithm.
- First, we calculate the LPS (Longest Prefix Suffix) array for the needle string.
- Then, we create a new string by concatenating needle, a special character (not present in either needle or haystack), and haystack.
- We iterate through the new string and compare characters using the LPS array to determine if there is a match.
- If the LPS value becomes equal to the length of the needle, it means we have found a match, and we return the starting index of the match in the haystack string.

Complexity Analysis:
- The time complexity of this solution is O(m + n), where m is the length of the needle and n is the length of the haystack.
- The space complexity is O(m + n) but can be reduced to O(n), where m is the length of the needle.

CODE:
*/

vector<int> lps(string& s){
    int n = s.size();
    vector<int> pi(n);
    for(int i = 1; i < n; i++){
        int j = pi[i - 1];
        while(j > 0 && s[j] != s[i]) {
            j = pi[j - 1];
        }
        if(s[j] == s[i]) {
            j++;
        }
        pi[i] = j;
    }
    return pi;
}

int strStr(string haystack, string needle) {
    if(needle.empty()) {
        return 0;
    }
    string temp = needle + '$' + haystack;
    vector<int> lpsArray = lps(temp);
    for(int i = 0; i < lpsArray.size(); i++) {
        if(lpsArray[i] == needle.size()) {
            return i - 2 * needle.size();
        }
    }
    return -1;
}

/*
QUESTION:
A string is called a happy prefix if it is a non-empty prefix that is also a suffix (excluding itself).

Given a string s, return the longest happy prefix of s. Return an empty string "" if no such prefix exists.

Example 1:
Input: s = "level"
Output: "l"
Explanation: s contains 4 prefixes excluding itself ("l", "le", "lev", "leve") and suffixes ("l", "el", "vel", "evel"). The largest prefix that is also a suffix is "l".

Approach:
- We can solve this problem using the KMP (Knuth-Morris-Pratt) algorithm.
- First, we calculate the LPS (Longest Prefix Suffix) array for the given string s.
- The last value in the LPS array, lps[n-1], represents the length of the longest prefix that is also a suffix.
- We extract the corresponding substring from s and return it as the longest happy prefix.

Complexity Analysis:
- The time complexity of this solution is O(n), where n is the length of the string s.
- The space complexity is O(n) to store the LPS array.

CODE:
*/

vector<int> kmp(string& s){
    int n = s.size();
    vector<int> pi(n);
    for(int i = 1; i < n; i++){
        int j = pi[i - 1];
        while(j > 0 && s[i] != s[j]) {
            j = pi[j - 1];
        }
        if(s[i] == s[j]) {
            j++;
        }
        pi[i] = j;
    }
    return pi;
}

string longestPrefix(string s) {
    int n = s.size();
    vector<int> lps = kmp(s);
    int length = lps[n - 1]; // Length of the longest prefix that is also a suffix
    return s.substr(0, length);
}

/*
QUESTION:
You are given a string s. You can convert s to a palindrome by adding characters in front of it.
Return the shortest palindrome you can find by performing this transformation.

Example 1:
Input: s = "aacecaaa"
Output: "aaacecaaa"

Approach:
1. We can solve this problem using the KMP (Knuth-Morris-Pratt) algorithm.
2. First, we reverse the string s and store it in the string rev.
3. We concatenate s and rev with a special character '$' in between, creating the string temp.
4. We calculate the LPS (Longest Prefix Suffix) array for the string temp using KMP.
5. The last value in the LPS array, lps.back(), represents the length of the longest prefix of temp that is also a suffix.
6. We extract the substring of s starting from index lps.back() to the end and reverse it.
7. Finally, we concatenate the reversed substring with s and return the result as the shortest palindrome.

Complexity Analysis:
- The time complexity of this solution is O(n), where n is the length of the string s.
- The space complexity is O(n) to store the LPS array.

CODE:
*/

vector<int> kmp(string& s) {
    int n = s.size();
    vector<int> pi(n);
    for(int i = 1; i < n; i++) {
        int j = pi[i - 1];
        while(j > 0 && s[i] != s[j]) {
            j = pi[j - 1];
        }
        if(s[i] == s[j]) {
            j++;
        }
        pi[i] = j;
    }
    return pi;
}

string shortestPalindrome(string s) {
    string rev = s;
    reverse(rev.begin(), rev.end());
    string temp = s + "$" + rev;
    vector<int> lps = kmp(temp);
    string toAdd = s.substr(lps.back());
    reverse(toAdd.begin(), toAdd.end());
    return toAdd + s;
}
